#!/usr/bin/env node
/* Builds page.js from wbcrypt-core.js + page.src.js (the board loads exactly one script per add-on).
   Run after editing either source:   node build.js
   Check that page.js is current:     node build.js --check   (exit 1 if page.js is stale) */
"use strict";
const fs = require("node:fs");
const path = require("node:path");

const core = fs.readFileSync(path.join(__dirname, "wbcrypt-core.js"), "utf8");
const src = fs.readFileSync(path.join(__dirname, "page.src.js"), "utf8");
const out =
  "/* GENERATED by build.js from wbcrypt-core.js and page.src.js. Do not edit; edit those and run `node build.js`. */\n" +
  core.replace(/\s+$/, "") + "\n\n" + src;

const target = path.join(__dirname, "page.js");
if (process.argv.includes("--check")) {
  let cur = ""; try { cur = fs.readFileSync(target, "utf8"); } catch (e) {}
  if (cur !== out) { console.error("page.js is out of date. Run: node build.js"); process.exit(1); }
  console.log("page.js is up to date.");
} else {
  fs.writeFileSync(target, out);
  console.log("Wrote page.js (" + out.length + " bytes).");
}
